import { useState } from "react";
import { useNavigate } from "react-router-dom";

const SignUp = () => {
    const navigate= useNavigate()
    const [signupData, setSignupData] = useState ({ 
        name: "",
        email: "",
        phone: "",
        password: ""
    });
    const [isError, setIsError] = useState(false);
    const [formError, setFormError] = useState(signupData);
    const validateFields = (name, value) => {
        switch (name) {
            case "name":
                if (value === "") {
                    return "Enter name";
                } else if (value.length < 3) {
                    return "Name should be greater than 3 characters";
                }
                break;
            case "email":
                if (value !== "") {
                    if (!/\S+@\S+\.\S+/.test(value)) {
                    return "Enter valid email";
                    }
                }
                break; 
            case "phone":
                if (value !== "") {
                     if (value.length !== 10 || !/^\d+$/.test(value)) {
                    return "Phone number should be 10 digits";
                    }
                }
                break;
                case "password":
                    if (value === "") {
                        return "Enter password";
                    } else if (value.length < 4 || value.length > 12) {
                        return "Password must be of 4-12 characters";
                    }
                    break;
        }
    }
    const handleChange = (event) => {
        let { name,value } = event.target;
        let error = validateFields(name, value);
        if (error) {
            setFormError((prev) => ({ ...prev, [name]: error }));
        } else {
            setFormError((prev) => ({ ...prev, [name]: "" }));
        }
        setSignupData({
            ...signupData,
            [name]: value
            })
    }
    const handleSubmit = (event) => {
        event.preventDefault();
        let validateForm={};
        Object.keys(signupData).forEach((fieldName) => {
            validateForm[fieldName] = validateFields(fieldName, signupData[fieldName]); 
    });
    
    if (Object.values(validateForm).some((error)=> error)) {
        setIsError(true);
        setFormError(validateForm);
    } else if (signupData.email === "" && signupData.phone === "") {
        setIsError(true);
    }
    else{
        setIsError(false);
        setFormError({});
        navigate("/netflixclon/login", { replace: true, state: { userId: signupData.email || signupData.phone,
            password: signupData.password } });
        
        
    }
    }

return(
    <div>
        <div className="flex flex-col" style={{ backgroundImage: "url(https://assets.nflxext.com/ffe/siteui/vlv3/fa4630b1-ca1e-4788-94a9-eccef9f7af86/web/IN-en-20250407-TRIFECTA-perspective_43f6a235-9f3d-47ef-87e0-46185ab6a7e0_medium.jpg)" }}>
            <div className="flex flex-col bg-gradient-to-b from-gray-900 from-10% to-transparent to-99%  h-full md:h-screen w-full">
                <div className="m-5 md:m-20 flex flex-col items-center ">
                    <div className="flex flex-1 items-center">
                        <div >
                            <img width={50} height={"auto"} src="https://static.vecteezy.com/system/resources/previews/024/273/839/original/netflix-logo-transparent-free-png.png" alt="Logo" />
                        </div>
                        <div className="text-2xl font-semibold uppercase">
                            Sign Up
                        </div>
                    </div>
                    <div className="flex flex-col items-center justify-center mt-5 w-full bg-black p  bg-opacity-80 rounded-lg p-10">
                    <h2 className="text-white text-2xl mb-3 ">Create an account</h2>
                    {isError && <span className="text-yellow-500 text-sm pb-3">Enter Email or mobile number</span>}
                    <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-4 items-center rounded-lg w-full md:w-1/2 text-stone-800">
                        <div className="flex flex-col relative">
                        <input type="text" name="name" value={signupData.name} placeholder="Name" onChange={handleChange} className="p-3 mb-3 w-full rounded-md" />
                        {formError.name && <span className="text-yellow-500 text-sm top-[50px] absolute">{formError.name}</span>}
                        </div>
                        <div className="flex flex-col relative">
                        <input type="text" name="email" value={signupData.email} onChange={handleChange} placeholder="Email" className="p-3 mb-3 w-full rounded-md" />
                        {formError.email && <span className="text-yellow-500 text-sm top-[50px] absolute">{formError.email}</span>}
                        </div>
                        <div className="flex flex-col relative">
                        <input type="text" name="phone" value={signupData.phone} onChange={handleChange} placeholder="Phone number" className="p-3 mb-3 w-full rounded-md" />
                        {formError.phone && <span className="text-yellow-500 text-sm top-[50px] absolute">{formError.phone}</span>}
                        </div>
                        <div className="flex flex-col relative">
                        <input type="password" name="password" value={signupData.password} onChange={handleChange} placeholder="Password" className="p-3 mb-3 w-full rounded-md" />
                        {formError.password && <span className="text-yellow-500 text-sm top-[50px] absolute">{formError.password}</span>}
                        </div>
                        
                        <button type="submit" className="col-span-2 mt-2 mb-5 bg-red-600 text-white p-3 rounded-md w-full">Sign Up</button>
                    </form>
                    </div>
                </div>
                
            </div>
        </div>
    </div>
)
}
export default SignUp;