import gsap from "gsap";
import { useEffect, useState } from "react";
import NavBar from "./NavBar";
import { useLocation } from "react-router-dom";
import Toast from "./Toast";
import { data, genres, languages } from "../Utilities/constants";
import Template from "./Template";


const Hero = () => {
  const location = useLocation();
  const { userName, authenticated } = location.state || { userName: "", authenticated: false };
  const [toastMessage, setToastMessage] = useState("");
  const [selectedObject, setSelectedObject] = useState(null);
  // useGSAP(
  const showToast = () => {
    setToastMessage("This application is meant for educational purposes only. Thus it is not intended for commercial use. The majority of the features are still in development, therefore you might not find them usable. When it's finished, these will be updated.");
    setTimeout(() => {
      setToastMessage("");
    }, 10000);
  }

  useEffect(() => {
    showToast();
    // const tl = gsap.timeline();


    // tl.fromTo("#hero",
    //   { opacity: 0, scale: 0.8, y: 0, },
    //   { opacity: 1, scale: 1.5, y: 0, duration: 2, ease: 'slow' }
    // );
    // tl.to("#title", {
    //   opacity: 1, delay: 0,
    // })

    // tl.to("#anime", {
    //   opacity: 1, delay: 0.5
    // }
    // )
    // tl.to(".sub", {
    //   opacity: 1, delay: 1
    // })
    // tl.to(
    //   ".note", {
    //   opacity: 1,
    //   color: "yellow",
    //   delay: 0.6,
    // }
    // )

    // return () => {
    //   tl.kill();
    // };

  }, []);

  return (
    <div className="relative w-screen h-full break-words">
      {toastMessage && <Toast message={toastMessage} />}
      <NavBar username={userName} isAuthenticated={authenticated} />

      <div className="h-full w-screen z-5">
        {
          selectedObject ? (
            <div className="flex flex-col h-full w-full items-center justify-center   max-md:mb-3 overflow-hidden bg-cover bg-top bg-opacity-25" style={{backgroundImage:`url(${selectedObject.bg_img})`}} >
              {/* <img src={selectedObject.bg_img} alt="" className="h-full w-screen object-cover opacity-[45%]" /> */}
              <div className="relative bg-gradient-to-t from-black from-3%  to-transparent to-90% h-full w-full flex flex-col items-center justify-center align-center">
                <div className="bg-black bg-opacity-30 px-20 py-10 md:py-5 w-full">
                  {/* {selectedObject.title} */}
                  <Template object={selectedObject} isAuthenticated={authenticated}/>
                </div>
                
              </div>
              </div>
          ):(
            <div className="relative bg-gradient-to-t from-black  to-transparent h-full w-full flex flex-col items-center justify-center align-center">
          <div className="flex flex-col items-center justify-center mt-10 mb-5 text-red-600 text-5xl sm:text-8xl font-bold opactiy-0 max-md:mb-3 overflow-hidden uppercase h-72">
            NetFlix
          </div>
        </div>
          )
        }
        

      </div>

      <div className="relative text-white p-5">
        <h1 className="text-md font-semibold opactiy-0 ">
          Trending Now
        </h1>
        <div className=" flex flex-1 h-full py-2 px-5 overflow-x-scroll overflow-y-hidden h-56 tiles mt-5">
          {
            data.map((obj, index) => (
              <div key={index} className="relative flex flex-col items-center justify-center align-center">
               <img  src={obj.asset} alt="" height={"auto"} onClick={()=>setSelectedObject(obj)} className="mr-1 max-w-[120px] max-h-full focus:ring-4 focus:ring-white-600" />
               {obj.recently_added && <div className="absolute bottom-0 bg-red-700 text-white text-xs font-semibold px-2 py-1 z-5">
                {obj.cID==="Ctg_001" ? "Recently Added":"New Episode"}
                
                </div>}
              </div>
              
              
            ))
          }
        
                            </div>
      </div>
      <div className="relative text-white p-5">
        <h1 className="text-md font-semibold opactiy-0 ">
          Upcoming Releases
        </h1>
        <div className=" flex flex-1 h-full py-2 px-5 overflow-x-scroll overflow-y-hidden h-56 tiles mt-5">
          {
            data.map((obj, index) => (
              <img key={index} src={obj.asset} alt="" height={"auto"}  className="mr-1 max-w-[120px] max-h-full focus:ring-4 focus:ring-white-600" />
            ))
          }
        
                            </div>
      </div>
      <div className="relative text-white p-5">
        <h1 className="text-md font-semibold opactiy-0 ">
          Worldwide Premiere
        </h1>
        <div className=" flex flex-1 h-full py-2 px-5 overflow-x-scroll overflow-y-hidden h-56 tiles mt-5">
          {
            data.map((obj, index) => (
              <img key={index} src={obj.asset} alt="" height={"auto"}  className="mr-1 max-w-[120px] max-h-full focus:ring-4 focus:ring-white-600" />
            ))
          }
        
                            </div>
      </div>

      <div className="relative text-white p-5">
        <h1 className="text-md font-semibold opactiy-0 ">
          Genre
        </h1>
        <div className="flex flex-row gap-5 items-center justify-start mt-5 overflow-x-scroll overflow-y-hidden tiles">
          {
            genres
              .sort((a, b) => a.genre_name.localeCompare(b.genre_name))
              .map((genre) => (
                <div key={genre.id} className="flex-shrink-0 px-5 py-3 w-52 h-16 bg-gray-600 rounded-lg text-sm font-semibold text-white hover:bg-gray-700 cursor-pointer transition duration-300 ease-in-out">
                  {genre.genre_name}
                </div>
              ))
          }
        </div>
      </div>
      <div className="flex flex-col  relative text-white p-5 ">
        <h1 className="text-md font-semibold opactiy-0 ">
          Languages
        </h1>
        <div className="flex flex-row flex-wrap gap-5 items-center justify-start mt-5">
          {
            languages.map((language) => (
              <div key={language.id} className="px-5 py-3 py-3 w-52 h-16 max-w-2xl bg-gray-600 rounded-lg text-sm font-semibold text-white hover:bg-gray-700 cursor-pointer transition duration-300 ease-in-out">
                {language.lang}
              </div>
            ))
          }
        </div>



      </div>


      {/* <section className="w-full h-screen">
            <div className="h-2/3 w-full flex items-center justify-center align-center flex-col gap-y-3">
                <p id="hero" className="text-red-600 mt-10 mb-5 text-5xl sm:text-8xl font-bold opactiy-0 max-md:mb-3 overflow-hidden uppercase">
                  <span id="title" className="opacity-0">N</span>
                    <span id="anime" className="opacity-0">etflix</span>
                </p>
                <div id="sub" className="flex flex-col text-white text-l sm:text-xl items-center justify-center text-center max-w-4xl  opacity-0 sub"> 
                    <div className="sub text-gray-300 text-base py-10 px-10 sm:px-20">This project was created for self-learning using React Js technology. The "NETFLIX" headline in the Hero section and the scroll control for the section below are animated using the GSAP library and the Tailwind CSS framework. <br/> <br/> <span className="note opacity-0">**The majority of the features are still in development, therefore you might not find them usable. When it's finished, these will be updated.</span> </div>
                </div>
                

            </div> 
            
        </section> */}
    </div>
  )
}

export default Hero;