import { useState } from "react";
import { logo } from "../Utilities/constants";
import { useLocation, useNavigate } from "react-router-dom";

const Login = () => {
    const navigation = useNavigate();
    const location=useLocation();
    const {userId}= location.state || {userId:""};
    const [formData, setFormData] = useState({
        userID: userId || "", 
        password: ""
    })
    const [formError, setFormError] = useState("");
    const handleChange = (event) => {
        let { name, value } = event.target;
        if (name === "userID" && value === "") {
            setFormError("Enter email or mobile number")
        }
        if (name === "password") {
            if (value === "") {
                setFormError("Enter password")
            } else if (value < 4 || value > 12) {
                setFormError("password must be of 4-12 charactes")
            }
        }

        setFormData({
            ...formData,
            [name]: value
        })
    }
    const loginSubmit = (event) => {

        event.preventDefault();

        const { userID, password } = formData;
        if (location.state) {
            if (password !== location.state.password) {
                setFormError("Invalid credentials");
            }
            else {
                alert("Login successful");
                navigation("/netflixclon/home", { replace: true, state: { userName:userID,
                    authenticated: true
                 } });
                setFormError("");
            }
        }else if (
            userID === "test123@mail.com" || userID === "1234567890"  &&
            password === "Test1234"
        ) {
            alert("Login successful");
            navigation("/netflixclon/home", { replace: true, state: { userName:userID,
                authenticated: true
             } });
            setFormError("");
        } else {
            setFormError("Unauthorized attempt to access");
        }
        console.log(formError)
        console.log(formData)
    }
    return (
        <div className="text-white w-
        screen 
        
        ">
            <div className="flex flex-col" style={{ backgroundImage: "url(https://assets.nflxext.com/ffe/siteui/vlv3/fa4630b1-ca1e-4788-94a9-eccef9f7af86/web/IN-en-20250407-TRIFECTA-perspective_43f6a235-9f3d-47ef-87e0-46185ab6a7e0_medium.jpg)" }}>
                <div className="flex flex-col bg-gradient-to-b from-gray-900 from-10% to-transparent to-99%  h-full md:h-screen w-full">
                    <div className="m-5 md:m-20 flex flex-col items-center ">
                        <div className="flex flex-1 items-center">
                            <div className="w-full md:w-1/2">
                                <img width={50} height={"auto"} src={logo} alt="Logo" />
                            </div>
                            <div className=" w-full md:w-1/2">
                                <span className="text-2xl font-semibold uppercase">Login</span></div>
                        </div>
                        <div className="mt-10 flex flex-col md:flex-row gap-5 bg-black w-full bg-opacity-80 items-start justify-center p-3 md:p-10">
                            <div className="w-full md:w-1/2 p-5">
                                <h1 className="text-3xl font-semibold pb-5">Instructions</h1>
                                <p>This site is for the demo pourpose only. Recommending not to use any personal data to avoid further security issues. <br /> For Login, use the following credentials

                                </p>
                                <ul className="list-disc px-5">
                                    <li>Email or mobile number - test123@mail.com / 1234567890</li>
                                    <li>password - Test1234</li>
                                </ul>
                                <div className="mt-10">
                                    <span className="text-white font-semibold">or</span> <br /> Try&nbsp; 
                                    <button type="button" className="text-red-600 font-bold underline" onClick={()=>navigation('/netflixclon/signup')} >Sign up</button> to create your own dummy credentials for this application. <br />
                                </div>
                            </div>
                            <div className="flex w-full md:w-1/2 justify-center text-stone-700 rounded-lg bg-opacity-90">
                                <form onSubmit={loginSubmit} className="flex flex-col gap-5 w-64 mt-2">

                                    <div className="flex flex-col gap-2">
                                        <input type="text" name="userID" id="email" value={formData.userID} onChange={handleChange} readOnly={location.state} placeholder="email or mobile number" className="px-2 py-2 rounded bg-gray-300" />
                                    </div>
                                    <div className="flex flex-col gap-2">
                                        <input type="password" name="password" id="password" value={formData.password} onChange={handleChange} placeholder="password" className="px-2 py-2 rounded bg-gray-300" />

                                    </div>
                                    {formError && <span className="text-sm text-yellow-500">{formError}</span>}
                                    <button type="submit" className="px-3 py-2 bg-red-600 text-white ">Login</button>
                                    <div className="text-stone-200">
                                        <input type="checkbox" name="" id="" />
                                        Remember me
                                    </div>
                                    <button type="button" disabled={true} className="text-stone-200 underline text-center">Forget Password</button>
                                </form>
                            </div>


                        </div>
                    </div>
                </div>


            </div>

        </div>
    )
}
export default Login;